def compute(vars):
    total_units = vars["v2"]
    vesting_units = vars["v1"]

    if total_units == 0:
        return None

    portion = vesting_units / total_units

    return {
        "value": portion,
        "trace": {
            "vesting_units": vesting_units,
            "total_units": total_units,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
